query:
SELECT state_name, state_code, status, incumbent, incumbent_party, candidate1_name, candidate1_party, candidate2_name, candidate2_party, primary_date, general_date, rating, notes
FROM senate_races WHERE state_code IN ('OR', 'KY') ORDER BY state_code;

SELECT state_code, district, status, incumbent, incumbent_party, candidate1_name, candidate1_party, candidate2_name, candidate2_party, primary_date, general_date, rating
FROM house_races WHERE state_code IN ('OR', 'KY') ORDER BY state_code, district;

